+	// Simulate the fixed version
+	prompt := &promptui.Select{
+		Label:    "Are you sure?",
+		HideHelp: true,
+		Items:    []string{answerApply, answerAbort},
+		Stdin:    os.Stdin,
+		Stdout:   os.Stdout,
+	}
+	
